#include "luca/pbmp.h"
#include "luca/irc.h"
#include <assert.h>
#include <string.h>
int main(void){struct luca_command_queue q;assert(luca_command_queue_init(&q)==0);struct luca_channel_registry cr;assert(luca_channel_registry_init(&cr,"#luca")==0);struct luca_pbmp_state s={"LuCa","irc.example","#luca",1,2,&q};s.channels=&cr;char b[2048];assert(luca_pbmp_response("{\"pbmp\":1,\"type\":\"request\",\"id\":\"42\",\"method\":\"bot.info\",\"params\":{}}",&s,b,sizeof b)==0);assert(strstr(b,"\"id\":\"42\""));assert(strstr(b,"\"implementation\":\"luca\""));assert(strstr(b,"\"state\":\"online\""));assert(luca_pbmp_response("{\"pbmp\":1,\"type\":\"request\",\"id\":\"9\",\"method\":\"x\",\"params\":{}}",&s,b,sizeof b)==0);assert(strstr(b,"not_supported"));assert(luca_pbmp_response("{\"pbmp\":1,\"type\":\"request\",\"id\":\"3\",\"method\":\"channels.list\",\"params\":{}}",&s,b,sizeof b)==0);assert(strstr(b,"\"name\":\"#luca\""));assert(luca_pbmp_response("{\"pbmp\":1,\"type\":\"request\",\"id\":\"4\",\"method\":\"capabilities.list\",\"params\":{}}",&s,b,sizeof b)==0);assert(strstr(b,"channels.list")&&strstr(b,"channels.join")&&strstr(b,"channels.part"));assert(luca_pbmp_response("{\"pbmp\":1,\"type\":\"request\",\"id\":\"5\",\"method\":\"channels.join\",\"params\":{\"network\":\"irc.example\",\"name\":\"#new\"}}",&s,b,sizeof b)==0);struct luca_command cmd;assert(luca_command_dequeue(&q,&cmd)==0);assert(cmd.type==LUCA_COMMAND_IRC&&strcmp(cmd.line,"JOIN #new")==0);assert(luca_pbmp_response("{\"pbmp\":1,\"type\":\"request\",\"id\":\"6\",\"method\":\"modules.reload\",\"params\":{\"id\":\"script.lua\"}}",&s,b,sizeof b)==0);assert(luca_pbmp_response("{\"pbmp\":1,\"type\":\"request\",\"id\":\"7\",\"method\":\"bot.info\",\"params\":{\"method\":\"channels.join\"}}",&s,b,sizeof b)==0);assert(strstr(b,"\"implementation\":\"luca\""));assert(luca_pbmp_response("{\"pbmp\":1,\"type\":\"request\",\"id\":\"a\",\"id\":\"b\",\"method\":\"bot.info\",\"params\":{}}",&s,b,sizeof b)!=0);luca_channel_registry_set(&cr,"#dynamic",1,0,0);luca_channel_registry_set(&cr,"#parted",0,0,0);assert(cr.count==4);int di=-1,pi=-1;for(unsigned i=0;i<cr.count;i++){if(!luca_irc_casecmp(cr.items[i].name,"#dynamic"))di=(int)i;if(!luca_irc_casecmp(cr.items[i].name,"#parted"))pi=(int)i;}assert(di>=0&&pi>=0);assert(cr.items[di].wanted==1);assert(cr.items[pi].wanted==0);luca_channel_registry_observe(&cr,"#DYNAMIC",1);assert(cr.items[di].joined==1);luca_channel_registry_observe(&cr,"#dynamic",0);assert(cr.items[di].joined==0&&cr.items[di].wanted==1);luca_command_queue_destroy(&q);return 0;}
